package com.chx.claims.identity.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){try{String[] p=h.substring(7).split("\\."); String json=new String(Base64.getUrlDecoder().decode(p[1])); String sub=value(json,"sub"),role=value(json,"role"); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(sub,null,List.of(new SimpleGrantedAuthority("ROLE_"+role))));}catch(Exception ignored){}} chain.doFilter(req,res);} private String value(String json,String key){String marker="\""+key+"\":\"";int i=json.indexOf(marker);if(i<0)return "";int s=i+marker.length(),e=json.indexOf('"',s);return json.substring(s,e);} }
